class Solution { public String reformatDate(String date){String[] parts=date.split(" ");List<String> months=Arrays.asList("Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec");int day=Integer.parseInt(parts[0].substring(0,parts[0].length()-2)),month=months.indexOf(parts[1])+1,year=Integer.parseInt(parts[2]);return String.format("%04d-%02d-%02d",year,month,day);} }
